  isDigitChar,
  splitPipeCells,
  trimLeftSpaces,
  trimRightSpaces,
  trimSpaces,
} from './text.mjs';

const BLOCK_TAGS = new Set([
  'address',
  'article',
  'aside',
  'blockquote',
  'body',
  'caption',
  'center',
  'col',
  'colgroup',
  'dd',
  'details',
  'dialog',
  'dir',
  'div',
  'dl',
  'dt',
  'fieldset',
  'figcaption',
  'figure',
  'footer',
  'form',
  'frame',
  'frameset',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'head',
  'header',
  'hr',
  'html',
  'iframe',
  'legend',
  'li',
  'main',
  'menu',
  'nav',
  'noframes',
  'ol',
  'p',
  'pre',
  'script',
  'section',
  'style',
  'summary',
  'table',
  'tbody',
  'td',
  'tfoot',
  'th',
  'thead',
  'title',
  'tr',
  'ul',
]);

const VOID_BLOCK_TAGS = new Set(['hr', 'col']);

export function renderBlocks(lines, mode) {
  const parts = [];
  let index = 0;

  while (index < lines.length) {
    if (isBlank(lines[index])) {
      index += 1;
      continue;
    }

    if (mode === 'extra') {
      const fence = parseFenceBlock(lines, index);
      if (fence !== null) {
        parts.push(fence.html);
        index = fence.nextIndex;
        continue;
      }
    }

    const htmlBlock = parseHtmlBlock(lines, index);
    if (htmlBlock !== null) {
      parts.push(htmlBlock.html);
      index = htmlBlock.nextIndex;
      continue;
    }

    if (isHorizontalRule(lines[index])) {
      parts.push('<hr />');
      index += 1;
      continue;
    }

    if (mode === 'tables' || mode === 'extra') {
      const table = parseTableBlock(lines, index);
      if (table !== null) {
        parts.push(table.html);
        index = table.nextIndex;
        continue;
      }
    }

    const heading = parseHeading(lines[index]);
    if (heading !== null) {
      parts.push(heading);
      index += 1;
      continue;
    }

    const blockquote = parseBlockquote(lines, index, mode);
    if (blockquote !== null) {
      parts.push(blockquote.html);
      index = blockquote.nextIndex;
      continue;
    }

    const list = parseList(lines, index);
    if (list !== null) {
      parts.push(list.html);
      index = list.nextIndex;
      continue;
    }

    const paragraph = parseParagraph(lines, index, mode);
    parts.push(paragraph.html);
    index = paragraph.nextIndex;
  }

  return parts.join('\n');
}

function parseFenceBlock(lines, startIndex) {
  const open = parseFenceOpen(lines[startIndex]);
  if (open === null) {
    return null;
  }

  let endIndex = startIndex + 1;

  while (endIndex < lines.length) {
    if (isFenceClose(lines[endIndex], open.tickCount)) {
      const bodyLines = lines.slice(startIndex + 1, endIndex);
      let body = bodyLines.join('\n');
      if (bodyLines.length > 0) {
