  const spaces = countLeadingSpaces(line);
  if (spaces > 3) {
    return false;
  }

  let index = spaces;
  let seen = 0;

  while (index < line.length && line[index] === '`') {
    seen += 1;
    index += 1;
  }

  if (seen < tickCount) {
    return false;
  }

  for (let i = index; i < line.length; i += 1) {
    const char = line[i];
    if (char !== ' ' && char !== '\t') {
      return false;
    }
