  let index = startIndex + 1;

  while (index < lines.length) {
    collected.push(lines[index]);
    if (lineContainsClosingTag(lines[index], start.tagName)) {
      return {
        html: collected.join('\n'),
        nextIndex: index + 1,
      };
    }
    index += 1;
  }

