  const marker = trimmed[0];
  if (marker !== '-' && marker !== '*' && marker !== '_') {
    return false;
  }

  let count = 0;

  for (let i = 0; i < trimmed.length; i += 1) {
    const char = trimmed[i];
    if (char === marker) {
      count += 1;
      continue;
    }
    if (char !== ' ' && char !== '\t') {
      return false;
    }
  }

  return count >= 3;
}

function parseTableBlock(lines, startIndex) {
  if (startIndex + 1 >= lines.length) {
    return null;
  }

  const headerCells = parseTableRow(lines[startIndex]);
  if (headerCells === null || headerCells.length === 0) {
    return null;
  }

  const alignments = parseTableDivider(lines[startIndex + 1]);
  if (alignments === null || alignments.length !== headerCells.length) {
    return null;
  }

  const bodyRows = [];
  let index = startIndex + 2;

  while (index < lines.length) {
    if (isBlank(lines[index])) {
      break;
    }

    const row = parseTableRow(lines[index]);
    if (row === null) {
      break;
    }

    bodyRows.push(normalizeCellCount(row, headerCells.length));
    index += 1;
  }

  let html = '<table>\n<thead>\n<tr>';

  for (let i = 0; i < headerCells.length; i += 1) {
    html += `\n<th${alignmentAttribute(alignments[i])}>${renderInline(headerCells[i])}</th>`;
  }

  html += '\n</tr>\n</thead>';

  if (bodyRows.length > 0) {
    html += '\n<tbody>';

    for (let rowIndex = 0; rowIndex < bodyRows.length; rowIndex += 1) {
      html += '\n<tr>';
      const row = bodyRows[rowIndex];
      for (let cellIndex = 0; cellIndex < headerCells.length; cellIndex += 1) {
        html += `\n<td${alignmentAttribute(alignments[cellIndex])}>${renderInline(row[cellIndex])}</td>`;
      }
      html += '\n</tr>';
    }

    html += '\n</tbody>';
  }

  html += '\n</table>';

  return {
    html,
    nextIndex: index,
  };
}

function parseTableRow(line) {
  if (line.indexOf('|') === -1) {
    return null;
  }

  const cells = splitPipeCells(line);
  if (cells.length === 0) {
    return null;
  }

  return cells;
}

function parseTableDivider(line) {
  const cells = parseTableRow(line);
  if (cells === null) {
    return null;
  }

  const alignments = [];

  for (let i = 0; i < cells.length; i += 1) {
    const alignment = parseAlignment(cells[i]);
    if (alignment === null) {
      return null;
    }
    alignments.push(alignment);
  }

  return alignments;
}

function parseAlignment(cell) {
  const text = trimSpaces(cell);
  if (text.length === 0) {
    return null;
  }

  let start = 0;
  let end = text.length;
  let left = false;
  let right = false;

  if (text[start] === ':') {
    left = true;
    start += 1;
  }

  if (end > start && text[end - 1] === ':') {
    right = true;
    end -= 1;
  }

  if (end <= start) {
    return null;
  }

  let dashCount = 0;

  for (let i = start; i < end; i += 1) {
    if (text[i] !== '-') {
      return null;
    }
    dashCount += 1;
  }

  if (dashCount === 0) {
    return null;
  }

  if (left && right) {
    return 'center';
  }

  if (left) {
    return 'left';
  }

  if (right) {
    return 'right';
  }

  return '';
}

function normalizeCellCount(cells, expectedCount) {
  const out = [];

  for (let i = 0; i < expectedCount; i += 1) {
    out.push(i < cells.length ? cells[i] : '');
  }

  return out;
}

function alignmentAttribute(alignment) {
  if (alignment.length === 0) {
    return '';
  }

  return ` style="text-align: ${alignment};"`;
}

function parseHeading(line) {
  let level = 0;

  while (level < line.length && line[level] === '#') {
    level += 1;
  }

  if (level < 1 || level > 6 || level >= line.length || line[level] !== ' ') {
    return null;
  }

  let content = trimSpaces(line.slice(level + 1));

  while (content.length > 0 && content[content.length - 1] === '#') {
    const stripped = trimRightSpaces(content.slice(0, content.length - 1));
    if (stripped.length === content.length - 1) {
      break;
    }
    content = stripped;
