export function normalizeNewlines(value) {
  let text = String(value ?? '');
  let out = '';

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];

    if (char === '\r') {
      if (i + 1 < text.length && text[i + 1] === '\n') {
        i += 1;
      }
      out += '\n';
      continue;
    }

    out += char;
  }

  return out;
}

export function splitLines(value) {
  return normalizeNewlines(value).split('\n');
}

export function countLeadingSpaces(line) {
  let count = 0;

  while (count < line.length && line[count] === ' ') {
    count += 1;
  }

  return count;
}

export function isBlank(line) {
  for (let i = 0; i < line.length; i += 1) {
    const char = line[i];
    if (char !== ' ' && char !== '\t') {
      return false;
    }
  }

  return true;
}

export function trimLeftSpaces(value) {
  let index = 0;

  while (index < value.length) {
    const char = value[index];
    if (char !== ' ' && char !== '\t') {
      break;
    }
    index += 1;
  }

  return value.slice(index);
}

export function trimRightSpaces(value) {
  let index = value.length;

  while (index > 0) {
    const char = value[index - 1];
    if (char !== ' ' && char !== '\t') {
      break;
    }
    index -= 1;
  }

  return value.slice(0, index);
}

export function trimSpaces(value) {
  return trimRightSpaces(trimLeftSpaces(value));
}

export function startsWithAt(text, prefix, index) {
  return text.slice(index, index + prefix.length) === prefix;
}

export function isDigitChar(char) {
  return char >= '0' && char <= '9';
}

export function isAsciiLetter(char) {
  const lower = char >= 'a' && char <= 'z';
  const upper = char >= 'A' && char <= 'Z';
  return lower || upper;
}

export function basename(path) {
  if (!path) {
    return '';
  }

  let splitAt = -1;

  for (let i = 0; i < path.length; i += 1) {
    const char = path[i];
    if (char === '/' || char === '\\') {
      splitAt = i;
    }
  }

  return splitAt === -1 ? path : path.slice(splitAt + 1);
}

export function containsWhitespace(text) {
  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    if (char === ' ' || char === '\t' || char === '\n' || char === '\r') {
      return true;
    }
  }

  return false;
}

export function splitPipeCells(line) {
  const cells = [];
  let current = '';
  let escaped = false;

  for (let i = 0; i < line.length; i += 1) {
    const char = line[i];

    if (escaped) {
      current += char;
      escaped = false;
      continue;
    }

    if (char === '\\') {
      current += char;
      escaped = true;
      continue;
    }

    if (char === '|') {
      cells.push(current);
      current = '';
      continue;
    }

    current += char;
  }

  cells.push(current);

  let start = 0;
  let end = cells.length;

  if (line.length > 0 && line[0] === '|') {
    start += 1;
  }

  if (line.length > 0 && line[line.length - 1] === '|') {
    end -= 1;
  }

  const out = [];

  for (let i = start; i < end; i += 1) {
    out.push(trimSpaces(cells[i]));
  }

  return out;
}

