export function escapeHtmlText(text) {
  let out = '';

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];

    if (char === '&') {
      out += '&amp;';
    } else if (char === '<') {
      out += '&lt;';
    } else if (char === '>') {
      out += '&gt;';
    } else {
      out += char;
    }
  }

  return out;
}

export function escapeHtmlAttribute(text) {
  let out = '';

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];

    if (char === '&') {
      out += '&amp;';
    } else if (char === '<') {
      out += '&lt;';
    } else if (char === '>') {
      out += '&gt;';
    } else if (char === '"') {
      out += '&quot;';
    } else {
      out += char;
    }
  }

  return out;
