export function renderMarkdown(text, mode = 'default') {
  const normalized = normalizeNewlines(text);
  if (normalized.length === 0) {
    return '';
  }

  return renderBlocks(splitLines(normalized), mode);
}

export function renderDefaultMarkdown(text) {
  return renderMarkdown(text, 'default');
}

